-- ==========================================================================
-- Static device -> station dimension, from silver.hw_config_current
-- Chicago / CTA-Ventra, 2026-07-26
--
-- PS1 lost facility, station, device name and component age because the
-- hw_config_current join was SKIPPED in all three v3 runs:
--     hw_config_current join skipped: No match for FieldRef.Name(COMPONENT_TYPE)
-- The join key COMPONENT_TYPE does not exist in that frame -- the column is
-- COMPONENT_DESCRIPTION. This file recovers the mapping from the source table
-- directly, so the dashboard does not have to wait for a notebook re-run.
--
-- Coverage measured against the PS1 export before generating:
--   devices           1,922 / 1,922  (100.0%)
--   device+serial     4,106 / 4,107  ( 99.98%)
--   device->facility  strictly 1:1
-- ==========================================================================

CREATE TABLE IF NOT EXISTS dim_device_station (
  city_id              city_code    NOT NULL REFERENCES cities(id),
  device_id            VARCHAR(40)  NOT NULL,
  device_key           NUMERIC(12,0),
  mars_device_category VARCHAR(12),
  facility_id          VARCHAR(20),
  facility_name        VARCHAR(120),
  operator_id          VARCHAR(20),
  operator_name        VARCHAR(80),
  as_of_date           DATE         NOT NULL,
  PRIMARY KEY (city_id, device_id)
);
CREATE INDEX IF NOT EXISTS idx_dim_dev_station_fac
  ON dim_device_station (city_id, facility_id);

-- Component identity per device serial. This is what PS1 needed for
-- component_type / component_age_days on the serial grain.
CREATE TABLE IF NOT EXISTS dim_device_component (
  city_id               city_code   NOT NULL REFERENCES cities(id),
  device_id             VARCHAR(40) NOT NULL,
  component_serial_nbr  VARCHAR(64) NOT NULL,
  component_description VARCHAR(120),
  component_age_days    NUMERIC(10,2),
  as_of_date            DATE        NOT NULL,
  PRIMARY KEY (city_id, device_id, component_serial_nbr)
);

DELETE FROM dim_device_component WHERE city_id='CHI';
DELETE FROM dim_device_station   WHERE city_id='CHI';



-- ---------------------------------------------------------------------
-- Backfill the PS1 rows that were loaded without facility or component.
-- ---------------------------------------------------------------------
UPDATE ps1_failure_predictions p
   SET facility_id = d.facility_id
  FROM dim_device_station d
 WHERE d.city_id = p.city_id AND d.device_id = p.device_id
   AND p.city_id = 'CHI' AND p.run_id = 'ps1_20260726';

UPDATE ps1_serial_predictions s
   SET component_type     = c.component_description,
       component_age_days = c.component_age_days
  FROM dim_device_component c
 WHERE c.city_id = s.city_id AND c.device_id = s.device_id
   AND c.component_serial_nbr = s.matched_serial_nbr
   AND s.city_id = 'CHI' AND s.run_id = 'ps1_20260726';

-- ---------------------------------------------------------------------
-- ps1_station_summary, built from the join rather than hand-seeded.
-- critical/high/medium counts come from the model's own risk_band, and
-- avg_risk_pct from the real probabilities -- no invented banding.
-- ---------------------------------------------------------------------
DELETE FROM ps1_station_summary WHERE city_id='CHI' AND computed_date=DATE '2026-07-26';

   critical_count, high_count, medium_count, last_inference_date, computed_date)
SELECT p.city_id,
       d.facility_id,
       COUNT(DISTINCT p.device_id),
       COUNT(*) FILTER (WHERE p.predicted_label = 1),
       ROUND(AVG(p.failure_probability) * 100, 3),
       COUNT(*) FILTER (WHERE p.risk_band = 'CRITICAL'),
       COUNT(*) FILTER (WHERE p.risk_band = 'HIGH'),
       COUNT(*) FILTER (WHERE p.risk_band = 'MEDIUM'),
       MAX(p.prediction_date),
       DATE '2026-07-26'
  FROM ps1_failure_predictions p
  JOIN dim_device_station d
    ON d.city_id = p.city_id AND d.device_id = p.device_id
 WHERE p.city_id = 'CHI' AND p.run_id = 'ps1_20260726'
   AND d.facility_id IS NOT NULL
 GROUP BY p.city_id, d.facility_id;
